import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"集成Swagger2","description":"","frontmatter":{"title":"集成Swagger2","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/03-实战-新蜂商城/集成Swagger2/集成Swagger2.md","filePath":"posts/java快速入门/第九部分：微服务/03-实战-新蜂商城/集成Swagger2/集成Swagger2.md"}'),i={name:"posts/java快速入门/第九部分：微服务/03-实战-新蜂商城/集成Swagger2/集成Swagger2.md"};function n(c,e,p,l,d,s){return t(),a("div",null,[...e[0]||(e[0]=[r('<div><p>现在公司中都使用前后端分离的方式进行开发，比如该项目就是一个纯后端框架。为了前后端更好的对接，就需要编写<code>API</code>文档。 然而手写<code>API</code>文档有如下几个痛点：</p><ul><li>功能修改后要及时更新文档，很容易出现功能文档不匹配</li><li>文档更新后，需要及时通知使用的人，很容易造成沟通不及时</li><li>接口参数和返回结果不明确</li><li>不能在线直接测试，需要借助工具，如<code>Postman</code></li><li>接口文档太多，不好进行管理</li></ul><p>这时我们今天的主角——<code>Swagger2</code>，顺利登场，说：这一些都不是问题。 那它到底为什么能够这么嚣张，它的效果又是怎么样的，我们下面来实际操作下。 <strong>具体实现</strong><strong>添加</strong><code>Maven</code><strong>依赖</strong></p><p>&lt;!--swagger2--&gt; &lt;dependency&gt; &lt;groupId&gt;io.springfox&lt;/groupId&gt; &lt;artifactId&gt;springfox-swagger2&lt;/artifactId&gt; &lt;version&gt;2.9.2&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;io.springfox&lt;/groupId&gt; &lt;artifactId&gt;springfox-swagger-ui&lt;/artifactId&gt; &lt;version&gt;2.9.2&lt;/version&gt; &lt;/dependency&gt; <strong>创建</strong><code>Swagger</code><strong>配置</strong> 新建 config 包，在 config 包中新增 SwaggerConfig.java，代码如下：</p><p>package ltd.newbee.mall.config; import io.swagger.annotations.ApiOperation; import springfox.documentation.service.Contact; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import springfox.documentation.builders.ApiInfoBuilder; import springfox.documentation.builders.PathSelectors; import springfox.documentation.builders.RequestHandlerSelectors; import springfox.documentation.service.ApiInfo; import springfox.documentation.spi.DocumentationType; import springfox.documentation.spring.web.plugins.Docket; import springfox.documentation.swagger2.annotations.EnableSwagger2; @Configuration @EnableSwagger2 public class SwaggerConfig {</p><p>@Bean</p><p>public Docket docket() {</p><p>return new Docket(DocumentationType.SWAGGER_2)</p><p>.select()</p><p>// apis 指定生成<code>API</code>的扫描条件</p><p>.apis(RequestHandlerSelectors.withMethodAnnotation(ApiOperation.class))</p><p>// 扫描包</p><p>// .apis(RequestHandlerSelectors.basePackage(&quot;com.zhuqc.framework.controller&quot;))</p><p>// paths 指定生成<code>API</code>的<code>path</code></p><p>.paths(PathSelectors.any())</p><p>.build()</p><p>// 文档信息</p><p>.apiInfo(apiInfo());   <code>}</code></p><p>private ApiInfo apiInfo() {</p><p>return new ApiInfoBuilder()</p><p>.title(&quot; 从零搭建后端框架</p><ul><li>&quot;)</li><li>.description(&quot;API</li></ul><p>接口文档</p><p>&quot;)</p><p>.termsOfServiceUrl(&quot;<a href="https://github.com/zhuqianchang/framework" target="_blank" rel="noreferrer">https://github.com/zhuqianchang/framework</a>&quot;)</p><p>.contact(new Contact(&quot;zhuqianchang&quot;, &quot;&quot;, &quot;&quot;))</p><p>.version(&quot;0.0.1&quot;)</p><p>.build();</p><p>} }</p><ul><li><code>@EnableSwagger2</code> 开启<code>Swagger2</code></li><li><code>apis</code> 用来指定扫描的条件</li><li><code>RequestHandlerSelectors.basePackage(&quot;com.zhuqc.framework.controller&quot;)</code>，扫描指定包</li><li><code>RequestHandlerSelectors.withClassAnnotation((Api.class)</code>，扫描<code>@Api</code>标注的类</li><li><code>RequestHandlerSelectors.withMethodAnnotation(ApiOperation.class)</code>，扫描<code>@ApiOperation</code>标注的方法</li><li><code>RequestHandlerSelectors.any()</code>，总是<code>true</code></li><li><code>RequestHandlerSelectors.none()</code>，总是<code>false</code></li><li>默认配置是没有<code>@ApiIgnore</code>标注的类和方法</li><li><code>paths</code> 用来指定生成<code>API</code>的<code>path</code></li><li><code>PathSelectors.any()</code>，总是<code>true</code></li><li><code>PathSelectors.none()</code>，总是<code>false</code></li><li><code>PathSelectors.regex()</code>，正则表达式匹配</li><li><code>PathSelectors.ant()</code>，<code>Ant</code>表达式匹配</li><li><code>apiInfo</code> 用来指定文档信息</li></ul><p>打开<a href="http://localhost:8080/swagger-ui.html" target="_blank" rel="noreferrer">Swagger UI</a></p></div>',1)])])}const f=o(i,[["render",n]]);export{u as __pageData,f as default};
